import routingRaw from "@/data/routing.json";
import type { APIRoute } from "astro";

// Public routing contract: the best system per use-case slice and topic.
// Althing reads it to pick a model or blend for a study.
//
// URL: https://synthbench.org/data/routing.json
//
// Generated by `synthbench publish-data --routing-output` from the same
// results and dedup as leaderboard.json. The payload carries its own
// `api.version` (semver; additive changes bump minor, consumers ignore
// unknown keys). Cache policy matches leaderboard.json (site/public/_headers).
//
// Docs: docs/routing-json-api.md

export const GET: APIRoute = () => {
  return new Response(JSON.stringify(routingRaw), {
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "public, max-age=3600, s-maxage=21600, stale-while-revalidate=86400",
      "Access-Control-Allow-Origin": "*",
    },
  });
};
